package main

import (
	"fmt"
	"go/format"
	"log"
	"sort"
	"strings"

	"github.com/tucats/govax/internal/link"
	"github.com/tucats/govax/internal/vmsdef"
)

// imagesFile is the generated file that holds SharedImages and
// ImageSymbols, in internal/vmsdef.
const imagesFile = "images_generated.go"

// readImage reads a shareable image file's global symbol table: its name,
// what its header says about it, and its universal symbols.
func readImage(data []byte) (string, vmsdef.SharedImage, map[string]vmsdef.ImageSymbol, error) {
	src, name, err := link.ReadShareableImage(data)
	if err != nil {
		return "", vmsdef.SharedImage{}, nil, err
	}

	i := src.Images[name]
	image := vmsdef.SharedImage{
		Pages:    i.Pages,
		MajorID:  i.MajorID,
		MinorID:  i.MinorID,
		Match:    uint32(i.Match),
		Symbols:  i.Symbols,
		Psects:   i.Psects,
		Sections: i.Sections,
	}

	symbols := make(map[string]vmsdef.ImageSymbol, len(src.Symbols))
	for n, d := range src.Symbols {
		symbols[n] = vmsdef.ImageSymbol{Image: d.Image, Value: d.Value}
	}

	return name, image, symbols, nil
}

// mergeImage merges one shareable image's facts and symbols into the
// tables, by the rules mergeSymbols follows.
func mergeImage(images map[string]vmsdef.SharedImage, symbols map[string]vmsdef.ImageSymbol,
	name string, image vmsdef.SharedImage, defs map[string]vmsdef.ImageSymbol, replace bool,
) mergeResult {
	var r mergeResult

	switch old, ok := images[name]; {
	case !ok:
		images[name] = image
		r.added = append(r.added, fmt.Sprintf("image %s %+v", name, image))

	case old == image:
		r.same++

	case replace:
		images[name] = image
		r.changed = append(r.changed, fmt.Sprintf("image %s: %+v -> %+v", name, old, image))

	default:
		r.conflicts = append(r.conflicts, fmt.Sprintf("image %s: %+v, not %+v", name, old, image))
	}

	names := make([]string, 0, len(defs))
	for n := range defs {
		names = append(names, n)
	}

	sort.Strings(names)

	for _, n := range names {
		d := defs[n]
		old, ok := symbols[n]

		switch {
		case !ok:
			symbols[n] = d
			r.added = append(r.added, fmt.Sprintf("%s = %s", n, imageSymbolString(d)))

		case old == d:
			r.same++

		case replace:
			symbols[n] = d
			r.changed = append(r.changed, fmt.Sprintf("%s: %s -> %s", n, imageSymbolString(old), imageSymbolString(d)))

		default:
			r.conflicts = append(r.conflicts, fmt.Sprintf("%s: %s, not %s", n, imageSymbolString(old), imageSymbolString(d)))
		}
	}

	return r
}

// imageSymbolString shows a symbol as an offset in its image, or as its
// absolute value.
func imageSymbolString(s vmsdef.ImageSymbol) string {
	if s.Image == "" {
		return fmt.Sprintf("%#x", s.Value)
	}

	return fmt.Sprintf("%s+%#x", s.Image, s.Value)
}

// generateImages returns the Go source of images_generated.go.
func generateImages(images map[string]vmsdef.SharedImage, symbols map[string]vmsdef.ImageSymbol, sources []string) []byte {
	var b strings.Builder

	fmt.Fprintf(&b, "// Code generated by internal/vmsdef/gen. DO NOT EDIT.\n\n")
	fmt.Fprintf(&b, "package vmsdef\n\n")

	fmt.Fprintf(&b, "// ImageSources names the shareable image files SharedImages and\n")
	fmt.Fprintf(&b, "// ImageSymbols were built from, in the order they were first merged.\n")
	fmt.Fprintf(&b, "var ImageSources = []string{\n")

	for _, s := range sources {
		fmt.Fprintf(&b, "\t%q,\n", s)
	}

	fmt.Fprintf(&b, "}\n\n")

	names := make([]string, 0, len(images))
	for n := range images {
		names = append(names, n)
	}

	sort.Strings(names)

	fmt.Fprintf(&b, "// SharedImages is what each shareable image's header says about it, by\n")
	fmt.Fprintf(&b, "// image name.\n")
	fmt.Fprintf(&b, "var SharedImages = map[string]SharedImage{\n")

	for _, n := range names {
		i := images[n]
		fmt.Fprintf(&b, "\t%q: {Pages: %d, MajorID: %d, MinorID: %#x, Match: %d, Symbols: %d, Psects: %d, Sections: %d},\n",
			n, i.Pages, i.MajorID, i.MinorID, i.Match, i.Symbols, i.Psects, i.Sections)
	}

	fmt.Fprintf(&b, "}\n\n")

	names = names[:0]
	for n := range symbols {
		names = append(names, n)
	}

	sort.Strings(names)

	fmt.Fprintf(&b, "// ImageSymbols is every universal symbol of the shareable images in\n")
	fmt.Fprintf(&b, "// SharedImages, by name.\n")
	fmt.Fprintf(&b, "var ImageSymbols = map[string]ImageSymbol{\n")

	for _, n := range names {
		s := symbols[n]
		if s.Image == "" {
			fmt.Fprintf(&b, "\t%q: {Value: %#x},\n", n, s.Value)
		} else {
			fmt.Fprintf(&b, "\t%q: {Image: %q, Value: %#x},\n", n, s.Image, s.Value)
		}
	}

	fmt.Fprintf(&b, "}\n")

	out, err := format.Source([]byte(b.String()))
	if err != nil {
		log.Fatalf("gen: generated images don't compile: %v", err)
	}

	return out
}
